SELECT pl.id, pl.no, pl.user_id AS userId, u.nickname AS userName, pl.prize_id AS prizeId, pm.name AS prizeName, pl.lottery_time AS lotteryTime, pl.cost_point AS costPoint, pl.status, pl.send_time AS sendTime, pl.sender_id AS senderId, pl.check_result AS checkResult, pl.sync_status AS syncStatus, pl.create_time AS createTime FROM point_lottery pl LEFT JOIN user_info u ON pl.user_id = u.id AND u.deleted = 0 LEFT JOIN prize_mgmt pm ON pl.prize_id = pm.id AND pm.deleted = 0 WHERE pl.deleted = 0
AND pl.no LIKE CONCAT('%', #{reqVO.no}, '%')
AND pl.user_id = #{reqVO.userId}
AND pl.prize_id = #{reqVO.prizeId}
AND pl.status = #{reqVO.status}
AND pl.sync_status = #{reqVO.syncStatus}
AND pl.sender_id = #{reqVO.senderId}
AND pl.check_result LIKE CONCAT('%', #{reqVO.checkResult}, '%')
AND pl.send_time BETWEEN #{reqVO.sendTime[0]} AND #{reqVO.sendTime[1]}
AND pl.lottery_time >= DATE(FROM_UNIXTIME(#{reqVO.startTime} / 1000))
AND pl.lottery_time <= DATE(FROM_UNIXTIME(#{reqVO.endTime} / 1000))
ORDER BY pl.id DESC

SELECT pl.user_id AS userId, u.nickname AS userName, pl.lottery_time AS joinTime, pm.activity_id AS joinActivityId, pa.name AS joinActivityName FROM point_lottery pl LEFT JOIN user_info u ON pl.user_id = u.id AND u.deleted = 0 LEFT JOIN prize_mgmt pm ON pl.prize_id = pm.id AND pm.deleted = 0 LEFT JOIN point_activity pa ON pm.activity_id = pa.id AND pa.deleted = 0 WHERE pl.deleted = 0
AND pl.lottery_time >= #{statStartTime}
AND pl.lottery_time <= #{statEndTime}
ORDER BY pl.id DESC
